WITH cleaned AS (SELECT id, txn_type, amount, txn_time, merchant, CAST(is_flagged AS INT) AS is_flagged_flag, LOWER(txn_type) AS txn_type_lower FROM transactions WHERE txn_time >= TIMESTAMP '2023-06-20 08:00:00' AND TO_DATE(txn_time) < '2024-01-27') SELECT * FROM (SELECT txn_type, merchant, amount FROM cleaned) src PIVOT (SUM(amount) AS total FOR merchant IN ('7-Eleven' AS v_7_eleven, 'Lazada' AS lazada, 'Grab' AS grab));
